package de.wattpit.app;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.widget.*;
import java.nio.charset.StandardCharsets;
import java.text.DateFormat;
import java.util.*;

/** Device-local optional destination, time and protected unattended password. */
public final class BackupActivity extends Activity {
    private SharedPreferences prefs;private Switch enabled;private EditText password,repeat,keep;private Button clock,save,now,choose;private TextView destination,status;private String validation="";private int hour,minute;private Uri selected;
    private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){showStatus();handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);prefs=BackupScheduler.prefs(this);ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,24,28,32);scroll.addView(root);setContentView(scroll);
        label(root,"Datensicherung",25);label(root,"Vollständige verschlüsselte Sicherung dieses Handys: Messwerte, Journale, Wetter, Lerngrundlagen, Einstellungen und Verbindungen. Für die gemeinsame Historie die Zentrale sichern; für eigene Layouts und lokale Daten bei Bedarf auch die Anzeigehandys.",16);
        enabled=new Switch(this);enabled.setText("Täglich automatisch sichern");enabled.setChecked(prefs.getBoolean("enabled",false));root.addView(enabled);hour=prefs.getInt("hour",3);minute=prefs.getInt("minute",0);clock=button(root,"",()->new TimePickerDialog(this,(v,h,m)->{hour=h;minute=m;clockText();},hour,minute,true).show());clockText();
        label(root,"Android führt die Sicherung ab dieser Ortszeit aus. Energiesparen kann sie verzögern. Versäumte Termine werden nachgeholt. Aufzeichnung bleibt aktiviert; Schreibzugriffe warten während des konsistenten Datenbankkopierens. Ein laufender Archivabruf wird zuerst abgewartet.",15);
        String uri=prefs.getString("tree","");if(!uri.isEmpty())selected=Uri.parse(uri);destination=label(root,"",16);choose=button(root,"Sicherungsordner wählen",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION),61);}catch(Exception e){validation="Kein kompatibler Speicheranbieter verfügbar.";showStatus();}});targetText();
        label(root,"Lokaler Ordner oder Online-Speicher, den Android als beschreibbaren Ordner anbietet. Die Anmeldung erfolgt beim Anbieter. Eine Verknüpfung nur im Dateimanager genügt nicht immer. Geprüft wird die zurückgelesene Datei beim Anbieter; dessen späteren Cloud-Upload steuert der Anbieter.",15);
        password=field(root,"Kennwort · mindestens 10 Zeichen",true);repeat=field(root,"Kennwort wiederholen",true);label(root,"Für automatische Läufe wird das Kennwort geschützt auf diesem Handy gespeichert. Für die Wiederherstellung auf einem anderen Handy brauchst du es selbst. Getrennt aufbewahren. Beide Felder leer lassen, um das Kennwort beizubehalten.",15);keep=field(root,"Sicherungsstände · 2 bis 30",false);keep.setInputType(InputType.TYPE_CLASS_NUMBER);keep.setText(""+prefs.getInt("keep",7));
        save=button(root,"Einstellungen speichern",()->configure(false));now=button(root,"Jetzt sichern",()->configure(true));status=label(root,"",16);button(root,"Sicherung wiederherstellen",()->startActivity(new Intent(this,MigrationActivity.class)));button(root,"Zurück",this::finish);
    }
    private TextView label(LinearLayout r,String v,int size){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setPadding(0,12,0,12);r.addView(t);return t;}
    private Button button(LinearLayout r,String v,Runnable action){Button b=new Button(this);b.setText(v);b.setAllCaps(false);r.addView(b);b.setOnClickListener(x->action.run());return b;}
    private EditText field(LinearLayout r,String v,boolean secret){EditText e=new EditText(this);e.setHint(v);if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);r.addView(e);return e;}
    private void clockText(){clock.setText(String.format(Locale.GERMANY,"Täglich ab %02d:%02d Uhr",hour,minute));}
    private void targetText(){destination.setText(selected==null?"Noch kein Sicherungsordner gewählt.":"Gewähltes Ziel: "+selected.getAuthority()+" · "+android.provider.DocumentsContract.getTreeDocumentId(selected));}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=61||result!=RESULT_OK||data==null||data.getData()==null)return;try{Uri uri=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&3)!=3)throw new IllegalArgumentException();getContentResolver().takePersistableUriPermission(uri,flags);selected=uri;validation="";targetText();}catch(Exception e){validation="Dauerhaften Lese- und Schreibzugriff auf den Ordner freigeben.";showStatus();}}
    private void configure(boolean run){if(DailyBackup.running()){validation="Bitte die laufende Sicherung abwarten.";showStatus();return;}byte[] bytes=null;try{
        int copies=Integer.parseInt(keep.getText().toString());if(copies<2||copies>30)throw new IllegalArgumentException("Bitte 2 bis 30 Stände wählen.");String text=password.getText().toString(),second=repeat.getText().toString(),secret=prefs.getString("password","");if(!text.isEmpty()||!second.isEmpty()){if(text.length()<10||!text.equals(second))throw new IllegalArgumentException("Mindestens zehn Zeichen und gleiche Kennwörter erforderlich.");bytes=text.getBytes(StandardCharsets.UTF_8);secret=KeyVault.encrypt(bytes);}
        if((run||enabled.isChecked())&&(selected==null||secret.isEmpty()))throw new IllegalArgumentException("Bitte Ordner und Kennwort festlegen.");SharedPreferences.Editor e=prefs.edit().putBoolean("enabled",enabled.isChecked()).putInt("hour",hour).putInt("minute",minute).putInt("keep",copies).putString("password",secret).putLong("due",BackupScheduler.nextTime(System.currentTimeMillis(),hour,minute)).remove("retry");if(selected!=null)e.putString("tree",selected.toString());if(!prefs.contains("owner"))e.putString("owner",UUID.randomUUID().toString().replace("-",""));if(!e.commit())throw new IllegalStateException();password.setText("");repeat.setText("");validation="";BackupScheduler.reconcile(this);if(run)BackupScheduler.now(this);showStatus();
        }catch(Exception e){validation=e instanceof IllegalArgumentException?e.getMessage():"Einrichtung fehlgeschlagen. Speicherzugriff prüfen.";showStatus();}finally{if(bytes!=null)Arrays.fill(bytes,(byte)0);}}
    private void showStatus(){if(status==null)return;boolean busy=DailyBackup.running();save.setEnabled(!busy);now.setEnabled(!busy);choose.setEnabled(!busy);long success=prefs.getLong("success",0),due=Math.max(prefs.getLong("due",0),prefs.getLong("retry",0));DateFormat f=DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT);String last=success==0?"Noch keine erfolgreiche Sicherung.":"Letzte geprüfte Sicherung: "+f.format(new Date(success))+" · "+(prefs.getLong("bytes",0)/1024)+" KB";status.setText((validation.isEmpty()?"":validation+"\n")+last+"\n"+(prefs.getBoolean("enabled",false)?"Nächster Termin ab "+f.format(new Date(due))+" (Ortszeit).":"Automatische Sicherung ausgeschaltet.")+"\n"+(busy?"Sicherung läuft …":prefs.getString("progress",""))+"\n"+prefs.getString("error",""));}
    @Override protected void onResume(){super.onResume();handler.post(tick);}@Override protected void onPause(){handler.removeCallbacks(tick);super.onPause();}
}
